// Some portions generated by Claude Code
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.within;

import org.eclipse.rdf4j.sail.lmdb.evaluation.LmdbNativeAgmBound.Edge;
import org.junit.jupiter.api.Test;

/**
 * Unit spec for the fractional-edge-cover bound.
 * <p>
 * The headline case is the triangle: three relations of {@code N} rows joined cyclically emit at most {@code N^1.5},
 * not the {@code N^3} an independence product predicts. Getting that exponent right is the whole point — it is the
 * difference between choosing a worst-case-optimal join on a cyclic query and never choosing it.
 */
public class LmdbNativeAgmBoundTest {

	private static final int A = 0;
	private static final int B = 1;
	private static final int C = 2;
	private static final int D = 3;

	private static long slots(int... slots) {
		long mask = 0L;
		for (int slot : slots) {
			mask |= 1L << slot;
		}
		return mask;
	}

	@Test
	public void triangleBoundIsNToThePowerOneAndAHalf() {
		double n = 1_000_000D;
		Edge[] triangle = {
				new Edge(slots(A, B), n),
				new Edge(slots(B, C), n),
				new Edge(slots(A, C), n),
		};

		double bound = LmdbNativeAgmBound.bound(triangle, slots(A, B, C));

		assertThat(Math.log(bound) / Math.log(n))
				.as("the optimal cover puts weight 1/2 on each edge, so the exponent is 3/2")
				.isCloseTo(1.5D, within(1e-6));
		assertThat(bound)
				.as("and it is far below the independence product, which is what makes leapfrog worth choosing")
				.isLessThan(n * n * n);
	}

	@Test
	public void singlePatternBoundIsItsOwnSize() {
		assertThat(LmdbNativeAgmBound.bound(new Edge[] { new Edge(slots(A, B), 250D) }, slots(A, B)))
				.isCloseTo(250D, within(1e-6));
	}

	@Test
	public void acyclicChainBoundIsTheProductBecauseNoEdgeSharesTheEndpoints() {
		// R(a,b), S(b,c): `a` appears only in R and `c` only in S, so both weights are forced to 1.
		double bound = LmdbNativeAgmBound.bound(new Edge[] {
				new Edge(slots(A, B), 1_000D),
				new Edge(slots(B, C), 2_000D),
		}, slots(A, B, C));

		assertThat(bound)
				.as("a tree has no cycle to exploit, so AGM degenerates to the product -- correctly, since a hash "
						+ "join beats leapfrog on this shape")
				.isCloseTo(2_000_000D, within(1D));
	}

	@Test
	public void disconnectedComponentsMultiply() {
		double bound = LmdbNativeAgmBound.bound(new Edge[] {
				new Edge(slots(A, B), 10D),
				new Edge(slots(C, D), 20D),
		}, slots(A, B, C, D));

		assertThat(bound).as("a cross product really is the product").isCloseTo(200D, within(1e-6));
	}

	@Test
	public void fourCycleBoundIsSquared() {
		// R(a,b), S(b,c), T(c,d), U(d,a): optimal cover takes two opposite edges, weight 1 each.
		double n = 1_000D;
		double bound = LmdbNativeAgmBound.bound(new Edge[] {
				new Edge(slots(A, B), n),
				new Edge(slots(B, C), n),
				new Edge(slots(C, D), n),
				new Edge(slots(D, A), n),
		}, slots(A, B, C, D));

		assertThat(Math.log(bound) / Math.log(n)).isCloseTo(2D, within(1e-6));
	}

	@Test
	public void aVertexNoEdgeCoversIsUnknownNotInfinite() {
		double bound = LmdbNativeAgmBound.bound(new Edge[] { new Edge(slots(A, B), 10D) }, slots(A, B, C));

		assertThat(bound)
				.as("unbounded must be reported as unknown; infinity would read as 'infinitely expensive'")
				.isNaN();
	}

	@Test
	public void unknownEdgeSizeMakesTheWholeBoundUnknown() {
		assertThat(LmdbNativeAgmBound.bound(new Edge[] {
				new Edge(slots(A, B), 10D),
				new Edge(slots(B, C), Double.NaN),
		}, slots(A, B, C))).isNaN();
	}

	@Test
	public void emptyEdgeSetBoundsOnlyTheEmptyJoin() {
		assertThat(LmdbNativeAgmBound.bound(new Edge[0], 0L)).isEqualTo(1D);
		assertThat(LmdbNativeAgmBound.bound(new Edge[0], slots(A))).isNaN();
	}

	@Test
	public void selfJoinOnOneVariableIsBoundedByTheSmallestRelation() {
		// Both patterns constrain the same single variable, so covering it with the cheaper one suffices.
		double bound = LmdbNativeAgmBound.bound(new Edge[] {
				new Edge(slots(A), 500D),
				new Edge(slots(A), 30D),
		}, slots(A));

		assertThat(bound).isCloseTo(30D, within(1e-6));
	}

	@Test
	public void boundIsNeverBelowTheLargestSingleRelationItMustCover() {
		// Sanity property rather than a specific number: any valid cover must pay for the vertices it covers.
		double bound = LmdbNativeAgmBound.bound(new Edge[] {
				new Edge(slots(A, B), 1_000D),
				new Edge(slots(B, C), 10D),
				new Edge(slots(A, C), 10D),
		}, slots(A, B, C));

		assertThat(bound).isGreaterThan(0D).isLessThan(1_000D * 10D * 10D);
	}
}
